// === Tab: Sketch ===
// By Roni Kaufman
// Inspired by Gustav Kimt's "The Kiss" (1907-1908)

let randInt = (a, b) => (floor(random(a, b)));

let margin = -80;
let minSize = 5;

let shapes;
let staticShapes; // shapes than don't grow anymore
let colors;

let n = 5; // number of generated squares per frame

function setup() {
	createCanvas(windowWidth, windowHeight);
	noStroke();
	background(94,36,16);

	shapes = [];
	staticShapes = [];
	let alpha = 20;
	/*
	colors = [color(247, 243, 242, alpha),
						color(0, 119, 225, alpha),
						color(245, 210, 22, alpha),
						color(252, 53, 3, alpha)];
	*/
	colors = [color(7,21,32, alpha),
						color(229,232,189, alpha),
						color(176,126,55, alpha),
						color(233,187,42, alpha),
						color(236,220,63, alpha)];
}

function draw() {
	for (let i = 0; i < n; i++) {
		let shape = {
			x: randInt(margin, width - margin - minSize),
			y: randInt(margin, height - margin - minSize),
			w: minSize,
			h: minSize,
			col: colors[floor(random(colors.length))]
		};
		if (canPutShape(shape)) {
			shapes.push(shape);
		}
	}

	growAndDrawShapes();
}

function canPutShape(newShape) {
	for (let s of shapes) {
		if (collude(s, newShape)) {
			return false;
		}
	}
	for (let s of staticShapes) {
		if (collude(s, newShape)) {
			return false;
		}
	}
	return true;
}

function growAndDrawShapes() {
	let i = 0;
	let _wG_1 = 0; while ((i < shapes.length) && ++_wG_1 < 20000) {
		let s = shapes[i];

		let wGrowth = randInt(1, 7);
		let hGrowth = randInt(1, 10);
		if (canGrow(i, wGrowth, hGrowth)) {
			s.w += wGrowth;
			s.h += hGrowth;
			fill(s.col);
			rect(s.x, s.y, s.w, s.h);
			i++
		} else {
			shapes.splice(i, 1);
			staticShapes.push(s);
		}
	}
}

function canGrow(i, wGrowth, hGrowth) {
	let si = {
		x: shapes[i].x,
		y: shapes[i].y,
		w: shapes[i].w + wGrowth,
		h: shapes[i].h + hGrowth
	};

	// right margin
	if (si.x + si.w + margin > width) {
		return false;
	}

	// bottom margin
	if (si.y + si.h + margin > height) {
		return false;
	}

	for (let j = 0; j < shapes.length; j++) {
		let sj = shapes[j];
		if (i != j && collude(si, sj)) {
			return false;
		}
	}
	for (let j = 0; j < staticShapes.length; j++) {
		var sj = staticShapes[j];
		if (collude(si, sj)) {
			return false;
		}
	}
	return true;
}

function collude(s1, s2) {
	if (s1.x === s2.x || s1.y === s2.y) {
		return true;
	}

	let xCollude1 = (s1.x < s2.x) && (s1.x + s1.w + margin > s2.x);
	let xCollude2 = (s1.x > s2.x) && (s2.x + s2.w + margin > s1.x);
	let xCollude = xCollude1 || xCollude2;

	let yCollude1 = (s1.y < s2.y) && (s1.y + s1.h + margin > s2.y);
	let yCollude2 = (s1.y > s2.y) && (s2.y + s2.h + margin > s1.y);
	let yCollude = yCollude1 || yCollude2;

	return xCollude && yCollude;
}
